from bcc import BPF, USDT, BPF
from bcc.utils import printb
import ctypes as ct
import time
import sys
import os

# BPF program for counting strlen return values
bpf_text_count = """
#include <uapi/linux/ptrace.h>

BPF_HISTOGRAM(retvals);

int count_strlen_ret(struct pt_regs *ctx) {
    int ret = PT_REGS_RC(ctx);
    retvals.increment(bpf_log2l(ret));
    return 0;
}
"""

# BPF program for submitting resolver and implementation addresses
bpf_text_submit = """
#include <uapi/linux/ptrace.h>

BPF_PERF_OUTPUT(events);

struct data_t {
    u64 resolver_addr;
    u64 impl_addr;
};

int submit_addrs(struct pt_regs *ctx) {
    struct data_t data = {};
    data.resolver_addr = (u64)PT_REGS_PARM1(ctx);
    data.impl_addr = (u64)PT_REGS_PARM2(ctx);
    events.perf_submit(ctx, &data, sizeof(data));
    return 0;
}
"""

def get_symbol_of_indirect_func(libc_path, func_name):
    from bcc import SymbolCache
    symcache = SymbolCache(-1, [libc_path])
    syms = []
    for sym in symcache.get_syms(libc_path):
        if sym.name == func_name:
            syms.append(sym)
    if not syms:
        raise Exception("Function %s not found in %s" % (func_name, libc_path))
    return syms[0]

def set_addresses_of_resolver_and_impl(libc_path, resolver_name, impl_name):
    from bcc import SymbolCache
    symcache = SymbolCache(-1, [libc_path])
    resolver_addr = None
    impl_addr = None
    for sym in symcache.get_syms(libc_path):
        if sym.name == resolver_name:
            resolver_addr = sym.addr
        if sym.name == impl_name:
            impl_addr = sym.addr
    if resolver_addr is None or impl_addr is None:
        raise Exception("Resolver or implementation function not found")
    return resolver_addr, impl_addr

def find_offset_of_impl_func(libc_path, impl_name):
    from bcc import SymbolCache
    symcache = SymbolCache(-1, [libc_path])
    for sym in symcache.get_syms(libc_path):
        if sym.name == impl_name:
            return sym.offset
    raise Exception("Implementation function not found")

def main():
    libc_path = BPF.find_library("c")
    if not libc_path:
        print("libc not found")
        sys.exit(1)

    # Get the symbol of the indirect function (strlen)
    strlen_sym = get_symbol_of_indirect_func(libc_path, "strlen")
    strlen_addr = strlen_sym.addr

    # Find the offset of the implementation function (__strlen_avx2 for example)
    # This may vary by system; you may need to adjust the implementation name
    impl_name = "__strlen_avx2"
    try:
        impl_offset = find_offset_of_impl_func(libc_path, impl_name)
    except Exception:
        # fallback to __strlen_sse2 or other known implementation
        impl_name = "__strlen_sse2"
        impl_offset = find_offset_of_impl_func(libc_path, impl_name)

    # Set the addresses of the resolver and implementation functions
    resolver_name = "__strlen_ifunc"
    resolver_addr, impl_addr = set_addresses_of_resolver_and_impl(libc_path, resolver_name, impl_name)

    # Load the counting BPF program
    b = BPF(text=bpf_text_count)
    # Attach to the implementation function
    b.attach_uprobe(name=libc_path, sym=impl_name, fn_name="count_strlen_ret", retprobe=True)

    print("Tracing strlen return values... Hit Ctrl-C to end.")

    while True:
        try:
            time.sleep(1)
            print("\nHistogram of strlen return values:")
            b["retvals"].print_log2_hist("strlen return")
            b["retvals"].clear()
        except KeyboardInterrupt:
            break

if __name__ == "__main__":
    main()
